import { useState, useCallback, useEffect, useRef } from "react";
import { useTheme } from "../context/ThemeContext";

// ─────────────────────────────────────────────────────────────────────────────
// ImageModal — full-screen lightbox with prev/next navigation
// ─────────────────────────────────────────────────────────────────────────────
function ImageModal({ images, startIndex, onClose }) {
  const [index, setIndex] = useState(startIndex);
  const image = images[index];
  const total = images.length;

  const prev = useCallback(() => setIndex((i) => (i - 1 + total) % total), [total]);
  const next = useCallback(() => setIndex((i) => (i + 1) % total), [total]);

  // Keyboard: Escape = close, ArrowLeft = prev, ArrowRight = next
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape")     onClose();
      if (e.key === "ArrowLeft")  prev();
      if (e.key === "ArrowRight") next();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, prev, next]);

  const handleBackdrop = useCallback(
    (e) => { if (e.target === e.currentTarget) onClose(); },
    [onClose]
  );

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={`Image preview: ${image.alt}`}
      className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-8"
      style={{ background: "rgba(7, 8, 9, 0.97)" }}
      onClick={handleBackdrop}
    >
      {/* Close */}
      <button
        onClick={onClose}
        className="absolute top-5 right-5 flex items-center gap-2 font-mono text-xs text-stone-500 hover:text-stone-200 transition-colors tracking-wider z-10"
        aria-label="Close image preview"
      >
        <span>ESC</span>
        <span className="text-base leading-none">✕</span>
      </button>

      {/* Counter */}
      <div className="absolute top-5 left-1/2 -translate-x-1/2 font-mono text-xs text-stone-600 tracking-widest">
        {index + 1} / {total}
      </div>

      {/* Prev arrow */}
      {total > 1 && (
        <button
          onClick={(e) => { e.stopPropagation(); prev(); }}
          className="absolute left-4 sm:left-6 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center border border-stone-700 text-stone-400 hover:border-accent-dim hover:text-accent transition-all duration-200 z-10"
          aria-label="Previous image"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>
      )}

      {/* Next arrow */}
      {total > 1 && (
        <button
          onClick={(e) => { e.stopPropagation(); next(); }}
          className="absolute right-4 sm:right-6 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center border border-stone-700 text-stone-400 hover:border-accent-dim hover:text-accent transition-all duration-200 z-10"
          aria-label="Next image"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M9 18l6-6-6-6" />
          </svg>
        </button>
      )}

      {/* Image */}
      <div className="relative w-full max-w-5xl mx-12 sm:mx-20">
        <img
          key={image.src}                        // remount on src change for clean transition
          src={image.src}
          alt={image.alt}
          className="w-full h-auto border border-wire shadow-2xl"
          style={{ maxHeight: "82vh", objectFit: "contain" }}
        />
        {/* Caption + dot indicators */}
        <div className="mt-4 flex items-center justify-between gap-4">
          <span className="font-mono text-xs text-stone-500 tracking-wider">
            {image.caption && <><span className="text-accent-glow mr-2">◆</span>{image.caption}</>}
          </span>
          {total > 1 && (
            <div className="flex items-center gap-1.5">
              {images.map((_, i) => (
                <button
                  key={i}
                  onClick={(e) => { e.stopPropagation(); setIndex(i); }}
                  className={`w-1.5 h-1.5 rounded-full transition-all duration-200 ${i === index ? "bg-accent-glow scale-125" : "bg-stone-700 hover:bg-stone-500"}`}
                  aria-label={`Go to image ${i + 1}`}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// ImageGallery
// ─────────────────────────────────────────────────────────────────────────────
// Replaces FeaturedImage + ThumbnailStrip with a unified component:
//   - Large featured image with prev/next arrow buttons on sides
//   - Arrow keyboard nav (← →) active when the gallery is focused/hovered
//   - Dot indicators below the image
//   - Click image → opens modal (also supports ← → in modal)
//   - Thumbnail strip below for quick jumping
//
// REPLACING IMAGES:
//   All sources come from portfolio.js → project.images[].src
//   No changes needed in this file.
// ─────────────────────────────────────────────────────────────────────────────
export function ImageGallery({ images, projectTitle }) {
  const [index, setIndex] = useState(0);
  const [hovered, setHovered] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const galleryRef = useRef(null);
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const total = images.length;
  const image = images[index];

  const prev = useCallback(() => setIndex((i) => (i - 1 + total) % total), [total]);
  const next = useCallback(() => setIndex((i) => (i + 1) % total), [total]);

  // Keyboard navigation — active only while hovering the gallery
  useEffect(() => {
    if (!hovered) return;
    const onKey = (e) => {
      if (e.key === "ArrowLeft")  { e.preventDefault(); prev(); }
      if (e.key === "ArrowRight") { e.preventDefault(); next(); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [hovered, prev, next]);

  if (!images || images.length === 0) return null;

  return (
    <>
      <div
        ref={galleryRef}
        className="flex flex-col select-none"
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
      >
        {/* ── FEATURED IMAGE AREA ─────────────────────────────────────────── */}
        <div
          className={`relative overflow-hidden border-b ${isDark ? "border-wire" : "border-wire-light"}`}
          style={{ aspectRatio: "16 / 9" }}
        >
          {/* Image — click opens modal */}
          <button
            className="absolute inset-0 w-full h-full focus:outline-none focus-visible:ring-1 focus-visible:ring-accent-dim"
            onClick={() => setModalOpen(true)}
            aria-label={`View full size: ${image.alt}`}
          >
            <img
              key={image.src}
              src={image.src}
              alt={image.alt}
              className="w-full h-full object-cover transition-transform duration-500 ease-out"
              style={{ transform: hovered ? "scale(1.025)" : "scale(1)" }}
              loading="lazy"
            />
          </button>

          {/* ── PREV ARROW ─────────────────────────────────────────────────── */}
          {total > 1 && (
            <button
              onClick={(e) => { e.stopPropagation(); prev(); }}
              className={`absolute left-3 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center
                border transition-all duration-200 z-10 backdrop-blur-sm
                ${isDark
                  ? "border-stone-700/80 bg-ink-950/70 text-stone-400 hover:border-accent-dim hover:text-accent hover:bg-ink-950/90"
                  : "border-gray-300/80 bg-white/70 text-gray-500 hover:border-accent-glow hover:text-accent-glow hover:bg-white/90"}
                ${hovered ? "opacity-100" : "opacity-0"}
                transition-opacity`}
              aria-label="Previous image"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                <path d="M15 18l-6-6 6-6" />
              </svg>
            </button>
          )}

          {/* ── NEXT ARROW ──────────────────────────────────────────────────── */}
          {total > 1 && (
            <button
              onClick={(e) => { e.stopPropagation(); next(); }}
              className={`absolute right-3 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center
                border transition-all duration-200 z-10 backdrop-blur-sm
                ${isDark
                  ? "border-stone-700/80 bg-ink-950/70 text-stone-400 hover:border-accent-dim hover:text-accent hover:bg-ink-950/90"
                  : "border-gray-300/80 bg-white/70 text-gray-500 hover:border-accent-glow hover:text-accent-glow hover:bg-white/90"}
                ${hovered ? "opacity-100" : "opacity-0"}
                transition-opacity`}
              aria-label="Next image"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                <path d="M9 18l6-6-6-6" />
              </svg>
            </button>
          )}

          {/* Hover overlay — "View Full Size" */}
          <div
            className="absolute inset-0 flex items-center justify-center transition-opacity duration-300 pointer-events-none"
            style={{ background: "rgba(7,8,9,0.45)", opacity: hovered ? 1 : 0 }}
            aria-hidden="true"
          >
            <div className="flex items-center gap-2 border border-accent-dim px-3 py-1.5 bg-ink-950/80 backdrop-blur-sm">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-accent">
                <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
              </svg>
              <span className="font-mono text-xs text-accent tracking-wider">View Full Size</span>
            </div>
          </div>

          {/* Caption watermark */}
          {image.caption && (
            <div className="absolute bottom-3 left-3 font-mono text-xs text-stone-500 tracking-wider opacity-70 pointer-events-none" aria-hidden="true">
              {image.caption}
            </div>
          )}

          {/* Image counter badge — top right */}
          {total > 1 && (
            <div className={`absolute top-3 right-3 font-mono text-xs px-2 py-0.5 pointer-events-none
              ${isDark ? "bg-ink-950/80 text-stone-500 border border-wire" : "bg-white/80 text-gray-400 border border-wire-light"}`}>
              {index + 1}/{total}
            </div>
          )}
        </div>

        {/* ── DOT INDICATORS + THUMBNAIL STRIP ───────────────────────────── */}
        {total > 1 && (
          <div className={`border-b ${isDark ? "border-wire bg-ink-950/40" : "border-wire-light bg-paper-100/40"}`}>

            {/* Thumbnail row */}
            <div className="flex gap-2 p-3">
              {images.map((img, i) => (
                <button
                  key={i}
                  onClick={() => setIndex(i)}
                  className={`relative flex-1 overflow-hidden transition-all duration-200 focus:outline-none
                    ${i === index
                      ? "ring-1 ring-accent-glow opacity-100"
                      : isDark ? "opacity-40 hover:opacity-70" : "opacity-50 hover:opacity-80"}`}
                  style={{ aspectRatio: "16/9" }}
                  aria-label={`View image ${i + 1}: ${img.caption || img.alt}`}
                  aria-pressed={i === index}
                >
                  <img
                    src={img.src}
                    alt={img.alt}
                    className="w-full h-full object-cover"
                    loading="lazy"
                  />
                </button>
              ))}
            </div>

            {/* Dot indicators */}
            <div className="flex items-center justify-center gap-1.5 pb-3">
              {images.map((_, i) => (
                <button
                  key={i}
                  onClick={() => setIndex(i)}
                  className={`rounded-full transition-all duration-200
                    ${i === index
                      ? "w-4 h-1.5 bg-accent-glow"
                      : `w-1.5 h-1.5 ${isDark ? "bg-stone-700 hover:bg-stone-500" : "bg-gray-300 hover:bg-gray-400"}`}`}
                  aria-label={`Go to image ${i + 1}`}
                />
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Modal lightbox */}
      {modalOpen && (
        <ImageModal
          images={images}
          startIndex={index}
          onClose={() => setModalOpen(false)}
        />
      )}
    </>
  );
}

// Keep old exports as aliases so nothing else breaks if referenced elsewhere
export const FeaturedImage = ({ image, projectTitle, images }) =>
  <ImageGallery images={images || [image]} projectTitle={projectTitle} />;

export const ThumbnailStrip = () => null; // absorbed into ImageGallery
